import{_ as l,a0 as s,w as d,s as r,I as o,x as t,a1 as p,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何在 FreeDOS 上歸檔文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 FreeDOS 上歸檔文件 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 FreeDOS 上歸檔文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 FreeDOS 上歸檔文件 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210628 How to archive files on FreeDOS","title":"如何在 FreeDOS 上歸檔文件","tag":"202107","desc":""},"relativePath":"202107/20210628 How to archive files on FreeDOS.md","filePath":"[post].md"}'),u={name:"202107/20210628 How to archive files on FreeDOS.md"};function m(f,e,Z,P,S,D){const i=s("Link");return d(),r("div",null,[e[22]||(e[22]=o("h1",{id:"如何在-freedos-上歸檔文件",tabindex:"-1"},[t("如何在 FreeDOS 上歸檔文件 "),o("a",{class:"header-anchor",href:"#如何在-freedos-上歸檔文件","aria-label":"Permalink to “如何在 FreeDOS 上歸檔文件”"},"​")],-1)),e[23]||(e[23]=o("blockquote",null,[o("p",null,"雖然有一個 FreeDOS 版的 tar，但 DOS 上事實上的標準歸檔工具是 Zip 和 Unzip。")],-1)),e[24]||(e[24]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/10/063340wp088ozz1fo9f1e1.jpg",alt:""})],-1)),e[25]||(e[25]=o("p",null,[t("在 Linux 上，你可能熟悉標準的 Unix 歸檔命令："),o("code",null,"tar"),t("。FreeDOS 上也有 "),o("code",null,"tar"),t(" 的版本（還有其他一些流行的歸檔程序），但 DOS 上事實上的標準歸檔程序是 Zip 和 Unzip。Zip 和 Unzip 都默認安裝在 FreeDOS 1.3 RC4 中。")],-1)),o("p",null,[e[1]||(e[1]=t("Zip 文件格式最初是由 PKWARE 的 Phil Katz 在 1989 年為 PKZIP 和 PKUNZIP 這對 DOS 歸檔工具構思的。Katz 將 Zip 文件的規範作為一個開放標準發佈，因此任何人都可以創建 Zip 檔案。作為開放規範的結果，Zip 成為 DOS 上的一個標準歸檔格式。",-1)),p(i,{href:"http://infozip.sourceforge.net/"},{default:n(()=>[...e[0]||(e[0]=[t("Info-ZIP",-1)])]),_:1}),e[2]||(e[2]=t(" 項目實現了一套開源的 ",-1)),e[3]||(e[3]=o("code",null,"ZIP",-1)),e[4]||(e[4]=t(" 和 ",-1)),e[5]||(e[5]=o("code",null,"UNZIP",-1)),e[6]||(e[6]=t(" 程序。",-1))]),e[26]||(e[26]=a('<h3 id="對文件和目錄進行壓縮" tabindex="-1">對文件和目錄進行壓縮 <a class="header-anchor" href="#對文件和目錄進行壓縮" aria-label="Permalink to “對文件和目錄進行壓縮”">​</a></h3><p>你可以在 DOS 命令列中使用 <code>ZIP</code> 來創建文件和目錄的歸檔。這是一個方便的方法，可以為你的工作做一個備份，或者發佈一個“包”，在未來的 FreeDOS 發佈中使用。例如，假設我想為我的項目源碼做一個備份，其中包含這些源文件：</p><p><img src="https://opensource.com/sites/default/files/uploads/dir.png" alt="dir" title="I&#39;d like to archive these files"></p><p><em>我想把這些文件歸檔</em></p><p><code>ZIP</code> 有大量的命令列選項來做不同的事情，但我最常使用的命令列選項是 <code>-r</code> 來處理目錄和子目錄 <em>遞歸</em>，以及使用 <code>-9</code> 來提供可能的最大壓縮。<code>ZIP</code> 和 <code>UNZIP</code> 使用類似 Unix 的命令列，所以你可以在破折號後面組合選項：<code>-9r</code> 將提供最大壓縮並在 Zip 文件中包括子目錄。</p><p><img src="https://opensource.com/sites/default/files/uploads/zip-9r.png" alt="zip" title="Zipping a directory tree"></p><p><em>壓縮一個目錄樹</em></p><p>在我的例子中，<code>ZIP</code> 能夠將我的源文件從大約 33KB 壓縮到大約 22KB，為我節省了 11KB 的寶貴磁盤空間。你可能會得到不同的壓縮率，這取決於你給 <code>ZIP</code> 的選項，或者你想在 Zip 文件中存儲什麼文件（以及有多少）。一般來説，非常長的文本文件（如源碼）會產生良好的壓縮效果，而非常小的文本文件（如只有幾行的 DOS “批處理”文件）通常太短，無法很好地壓縮。</p><h3 id="解壓文件和目錄" tabindex="-1">解壓文件和目錄 <a class="header-anchor" href="#解壓文件和目錄" aria-label="Permalink to “解壓文件和目錄”">​</a></h3><p>將文件保存到 Zip 文件中是很好的，但你最終會需要將這些文件解壓到某個地方。讓我們首先檢查一下我們剛剛創建的 Zip 文件裏有什麼。為此，使用 <code>UNZIP </code>命令。你可以在 <code>UNZIP</code>中使用一堆不同的選項，但我發現我只使用幾個常用的選項。</p><p>要列出一個 Zip 文件的內容，使用 <code>-l</code> （“list”） 選項。</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-l.png" alt="unzip -l" title="Listing the archive file contents with unzip"></p><p><em>用 unzip 列出歸檔文件的內容</em></p><p>該輸出允讓我看到 Zip 文件中的 14 個條目：13 個文件加上 <code>SRC</code> 目錄。</p><p>如果我想提取整個 Zip 文件，我可以直接使用 <code>UNZIP</code> 命令並提供 Zip 文件作為命令列選項。這樣就可以從我當前的工作目錄開始提取 Zip 文件了。除非我正在恢復某個東西的先前版本，否則我通常不想覆蓋我當前的文件。在這種情況下，我希望將 Zip 文件解壓到一個新的目錄。你可以用 <code>-d</code> （“destination”） 命令列選項指定目標路徑。</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-d.png" alt="unzip -d temp" title="You can unzip into a destination path with -d"></p><p><em>你可以用 -d 來解壓到目標路徑</em></p><p>有時我想從一個 Zip 文件中提取一個文件。在這個例子中，假設我想提取一個 DOS 可執行程序 <code>TEST.EXE</code>。要提取單個文件，你要指定你想提取的 Zip 文件的完整路徑。默認情況下，<code>UNZIP</code> 將使用 Zip 文件中提供的路徑解壓該文件。要省略路徑信息，你可以添加 <code>-j</code>（“junk the path”） 選項。</p><p>你也可以組合選項。讓我們從 Zip 文件中提取 <code>SRC\\TEST.EXE</code> 程序，但省略完整路徑並將其保存在 <code>TEMP</code> 目錄下：</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-j.png" alt="unzip -j" title="Combining options with unzip"></p><p><em>unzip 組合選項</em></p><p>因為 Zip 文件是一個開放的標準，所以我們會今天繼續看到 Zip 文件。每個 Linux 發行版都可以通過 Info-ZIP 程序支持 Zip 文件。你的 Linux 文件管理器可能也支持 Zip 文件。在 GNOME 文件管理器中，你應該可以右擊一個文件夾並從下拉菜單中選擇“壓縮”。你可以選擇創建一個包括 Zip 文件在內的新的歸檔文件。</p><p>創建和管理 Zip 文件是任何 DOS 用户的一項關鍵技能。你可以在 Info-ZIP 網站上了解更多關於 <code>ZIP</code> 和 <code>UNZIP</code> 的信息，或者在命令列上使用 <code>h</code>（“幫助”）選項來打印選項列表。</p><hr>',24)),o("p",null,[e[8]||(e[8]=t("via: ",-1)),p(i,{href:"https://opensource.com/article/21/6/archive-files-freedos"},{default:n(()=>[...e[7]||(e[7]=[t("https://opensource.com/article/21/6/archive-files-freedos",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=t("作者：",-1)),p(i,{href:"https://opensource.com/users/jim-hall"},{default:n(()=>[...e[9]||(e[9]=[t("Jim Hall",-1)])]),_:1}),e[14]||(e[14]=t(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[10]||(e[10]=[t("lujun9972",-1)])]),_:1}),e[15]||(e[15]=t(" 譯者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:n(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[16]||(e[16]=t(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[t("Linux中國",-1)])]),_:1}),e[21]||(e[21]=t(" 榮譽推出",-1))])])}const O=l(u,[["render",m]]);export{I as __pageData,O as default};
